using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.GameStates;
using FMODUnity;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class ActionInstance : ZoomableInstance
{
	protected const float endDragAnimDuration = 0.2f;

	[Header("Drag and Drop")]
	[SerializeField]
	protected AnimationCurve endDragAnimCurve;

	[Header("Components")]
	[SerializeField]
	protected Image actionFaceImage;

	[SerializeField]
	protected ActionInstanceTrailHandler actionInstanceTrailHandler;

	[SerializeField]
	protected ActionInstanceOutlineHandler actionInstanceOutlineHandler;

	[Header("Tooltip")]
	[SerializeField]
	private GameObjectReference actionDescriptionActionOwnerReference;

	[Header("Parallax")]
	[SerializeField]
	protected FloatReference parallaxMovementAmountFloatReference;

	[Header("SFX")]
	[SerializeField]
	private EventReference uiDeckVirtuePickSFX;

	[SerializeField]
	private EventReference uiDiceVirtueDropSFX;

	[SerializeField]
	private EventReference cantUseActionSFX;

	protected DiceOwnerEnum diceOwnerEnum;

	protected GameObject actionOwner;

	protected bool actionEnabled;

	private Vector3 originalCastPosition;

	[ShowNonSerializedField]
	protected bool disableDiscard;

	protected bool dragging;

	public bool Discarding;

	protected List<GameState> pointAndClickDraggableStates;

	protected ActionFace actionFace => GetActionFace();

	public ActionFace ActionFace => GetActionFace();

	public DiceOwnerEnum DiceOwnerEnum => diceOwnerEnum;

	public GameObject ActionOwner => actionOwner;

	public bool ActionEnabled => actionEnabled;

	public Vector3 OriginalCastPosition => originalCastPosition;

	public bool DisableDiscard => disableDiscard;

	public bool Dragging => dragging;

	protected GameStateManager gameStateManager => ReferenceSingleton<GameStateManager>.Instance;

	protected bool isOnChooseActionState => gameStateManager.IsOnChooseActionState;

	private GameState currentState => gameStateManager.CurrentState;

	private void OnDisable()
	{
		OnMouseExitOnlyTooltip();
	}

	public void InitializeActionInstance(ActionInstanceData actionInstanceData)
	{
		Discarding = false;
		pointAndClickDraggableStates = actionInstanceData.PointAndClickDraggableStates;
		if (actionInstanceData.EnablePanelPosition)
		{
			actionDescriptionPanelPosition.localPosition = actionInstanceData.ActionDescriptionPanelPosition;
		}
	}

	public override void InitializeActionDescriptionPanel()
	{
		actionDescriptionActionOwnerReference.Set(actionOwner);
		if (GameScenesUtils.IsBattleScene())
		{
			ReferenceSingleton<BattleHandler>.Instance.SetActionDescriptionActionInstance(this);
		}
	}

	public void DiceDragInputComputed()
	{
		dragging = true;
		actionFaceImage.raycastTarget = false;
		ResetScale();
		if (this is DiceInstance)
		{
			(this as DiceInstance).SetupDiceToStartFollowingMouse();
		}
	}

	protected bool ActionSelectedCheckConditionToBeCastedWithActionValue(bool playerHand)
	{
		if (!actionFace.BattleAction.CheckConditionToBeCasted(playerHand, diceOwnerEnum) || !actionFace.BattleAction.CheckConditionToBeCasted(actionFace.ModifiedActionValue) || !actionFace.BattleAction.CheckConditionToBeCasted(actionFace.ModifiedActionValue, playerHand, diceOwnerEnum))
		{
			PlayCantUseActionFeedback();
			return false;
		}
		return true;
	}

	protected void ActionSelected()
	{
		actionInstanceOutlineHandler.StopShakeCoroutine();
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDeckVirtuePickSFX);
		ResetScale();
		SpawnTrail();
		if (isOnChooseActionState)
		{
			ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(this);
			actionFace.BattleAction.GetDiceActionLogic(actionFace.ModifiedActionValue).ActionGrabbed();
		}
	}

	public void PlayCantUseActionFeedback()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(cantUseActionSFX);
		actionInstanceOutlineHandler.Shake();
	}

	private void ActionCanceled()
	{
		if (currentState != gameStateManager.ChooseDiceState && currentState != gameStateManager.ChooseEnemyDiceState && currentState != gameStateManager.ChoosePlayerDiceState)
		{
			gameStateManager.SetState(gameStateManager.NoInteractionState);
		}
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDiceVirtueDropSFX);
		GoBackToOriginalPositionAnimation(returningToHandAfterDrag: true);
	}

	public virtual bool StartFollowingMouse()
	{
		if (isOnChooseActionState && !actionFace.BattleAction.CheckConditionToBeCasted(actionFace.ModifiedActionValue))
		{
			PlayCantUseActionFeedback();
			return false;
		}
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: false);
		actionFaceImage.raycastTarget = false;
		dragging = true;
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			originalCastPosition = base.transform.position;
		});
		ActionSelected();
		return true;
	}

	public bool CanDrag(GameState gameState = null)
	{
		if (gameState == null)
		{
			gameState = currentState;
		}
		if (!pointAndClickDraggableStates.Contains(gameState) || !actionEnabled || Discarding)
		{
			return false;
		}
		return true;
	}

	public virtual void StopFollowingMouse()
	{
		if (base.gameObject.activeInHierarchy && !Discarding)
		{
			ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
			dragging = false;
			ActionCanceled();
		}
	}

	public virtual void ActionDroppedOnBattleActionCastSpace()
	{
		dragging = false;
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		actionFaceImage.raycastTarget = true;
		if (this is RuneInstance)
		{
			actionInstanceTrailHandler.SetParticlesLayer(0);
		}
		actionInstanceOutlineHandler.ToggleOutline(toggle: false);
	}

	public virtual bool JoystickActionSelected()
	{
		ActionSelected();
		OnMouseExit();
		return true;
	}

	public virtual void JoystickActionCanceled()
	{
		ActionCanceled();
	}

	public virtual void GoBackToOriginalPositionAnimation(bool returningToHandAfterDrag = false, System.Action afterGoBackToOriginalPositionAction = null)
	{
		actionInstanceTrailHandler.OnGoBackToOriginalPositionAnimation((this is DiceInstance) ? 6 : 10);
	}

	public virtual void AfterGoBackToOriginalPositionAnimation(System.Action afterGoBackToOriginalPositionAction = null)
	{
		if (currentState != gameStateManager.ChooseDiceState && currentState != gameStateManager.ChoosePlayerDiceState && currentState != gameStateManager.ChooseEnemyDiceState && currentState != gameStateManager.ActionsQueueState && currentState != gameStateManager.ChooseActionState && currentState != gameStateManager.ChooseDiceOnPoolState && currentState != gameStateManager.DeathState && currentState != gameStateManager.PrecisionActionState && currentState != gameStateManager.EndPlayerTurnState && currentState != gameStateManager.CorruptPlayerState)
		{
			bool flag = true;
			if (this is DiceInstance && DiceOwnerEnum == DiceOwnerEnum.COMPANION && ReferenceSingleton<GameStateManager>.Instance.NoEnterChooseActionStates.Contains(currentState))
			{
				flag = false;
			}
			if (flag)
			{
				gameStateManager.SetChooseActionState();
			}
		}
		bool flag2 = true;
		if (this is DiceInstance && DiceOwnerEnum == DiceOwnerEnum.COMPANION && ReferenceSingleton<GameStateManager>.Instance.NoEnterChooseActionStates.Contains(currentState))
		{
			flag2 = false;
		}
		if (flag2)
		{
			ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
		}
		actionFaceImage.raycastTarget = true;
		afterGoBackToOriginalPositionAction?.Invoke();
		StoreTrail();
	}

	public virtual void DisposeAction()
	{
		Discarding = true;
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		dragging = false;
		actionFaceImage.raycastTarget = true;
		actionInstanceTrailHandler.OnDisposeAction();
		actionInstanceOutlineHandler.ToggleOutline(toggle: false);
		if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			ReferenceSingleton<InputManager>.Instance.ResetPreviousIndexes();
		}
	}

	public void StoreTrail()
	{
		actionInstanceTrailHandler.StoreTrail();
	}

	private void SpawnTrail()
	{
		actionInstanceTrailHandler.SpawnTrail((this is DiceInstance) ? 6 : 10);
	}

	public void KillTrail()
	{
		actionInstanceTrailHandler.KillTrail();
	}

	protected virtual ActionFace GetActionFace()
	{
		return null;
	}

	public void SetDragging(bool value)
	{
		dragging = value;
	}

	public void SetDisableDiscard(bool value)
	{
		disableDiscard = value;
	}

	public bool IsFollowingMouse()
	{
		return dragging;
	}
}
